  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fill("#87ceeb", 100); // sky
  brush.fill("#7cfc00", 60);  // eastern sky
  brush.fill("#d8b671", 30);  // eastern horizon
  brush.fill("#d2b48c", 80);  // western sky
  brush.fill("#9e733f", 30);  // western horizon

  // hills
  brush.fill("#b2a77f", 60);  // grass
  brush.fill("#8d8d8d", 50);  // darker grass
  brush.fill("#7d7d7d", 40);  // darker grass
  brush.fill("#7e7e7e", 30);  // darkest grass
  brush.fill("#7e7e7e", 30);  // darkest grass

  brush.fillBleed(0.5);       // soft edges
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(300, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  brush.fillTexture(0.5, true); // soft texture on hills
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(300, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  brush.fill("#7cfc00", 60);  // sun
